export async function createRoom(actor:string,pid:string,titleValue:string,key:string){const db=database(),title=text(titleValue,'회의 주제 이름',500),receiptKey=actor+':room:'+text(key,'Idempotency-Key',120),fingerprint=await hash(JSON.stringify({pid,title,action:'create_room'}));const old=await db.prepare('SELECT * FROM hub_receipts WHERE key=?').bind(receiptKey).first<any>();if(old){if(old.fingerprint!==fingerprint)throw new HubError(409,'같은 요청 키로 다른 회의를 만들 수 없습니다.');return {...JSON.parse(old.response),replayed:true};}const roomId=uid(),now=stamp(),result={roomId,title,status:'ready'};try{await db.batch([db.prepare("INSERT INTO hub_rooms(id,project,title,status,created_at,updated_at) VALUES(?,?,?,'ready',?,?)").bind(roomId,pid,title,now,now),db.prepare('INSERT INTO hub_receipts(key,actor,fingerprint,response,created_at) VALUES(?,?,?,?,?)').bind(receiptKey,actor,fingerprint,JSON.stringify(result),now)]);}catch{const retry=await db.prepare('SELECT * FROM hub_receipts WHERE key=?').bind(receiptKey).first<any>();if(retry&&retry.fingerprint===fingerprint)return {...JSON.parse(retry.response),replayed:true};throw new HubError(409,'회의 생성 요청이 충돌했습니다.');}await event(actor,pid,'room.create',roomId);return result;}

export async function startRoom(actor:string,pid:string,topic:string,key:string,initialMessage?:string){
  const db=database(),title=text(topic,'대화 주제',500),message=initialMessage===undefined?title:text(initialMessage,'음성 지시'),receiptKey=actor+':'+text(key,'Idempotency-Key',120),fingerprint=await hash(JSON.stringify({pid,title,...(initialMessage===undefined?{}:{message})}));
  const old=await db.prepare('SELECT * FROM hub_receipts WHERE key=?').bind(receiptKey).first<any>();
  if(old){if(old.fingerprint!==fingerprint)throw new HubError(409,'같은 요청 키로 다른 대화를 만들 수 없습니다.');return {...JSON.parse(old.response),replayed:true};}
  const rid=uid(),mid=uid(),now=stamp(),result={roomId:rid};
  try{await db.batch([
    db.prepare("INSERT INTO hub_rooms(id,project,title,status,created_at,updated_at) VALUES(?,?,?,'director_thinking',?,?)").bind(rid,pid,title,now,now),
    db.prepare("INSERT INTO hub_messages(id,room_id,project,sender,body,created_at) VALUES(?,?,?,'chief',?,?)").bind(mid,rid,pid,message,now),
    db.prepare('INSERT INTO hub_receipts(key,actor,fingerprint,response,created_at) VALUES(?,?,?,?,?)').bind(receiptKey,actor,fingerprint,JSON.stringify(result),now),
  ]);}catch{const retry=await db.prepare('SELECT * FROM hub_receipts WHERE key=?').bind(receiptKey).first<any>();if(retry&&retry.fingerprint===fingerprint)return {...JSON.parse(retry.response),replayed:true};throw new HubError(409,'대화 생성 요청이 충돌했습니다.');}
  await event(actor,pid,'room.start',rid);return {...result,director:await generateDirector(mid)};
}
export async function sendChief(actor:string,pid:string,rid:string,value:string,key:string){
  const db=database(),roomId=text(rid,'대화 ID',100),message=text(value,'메시지'),receiptKey=actor+':'+text(key,'Idempotency-Key',120);
  const fingerprint=await hash(JSON.stringify({pid,roomId,message}));
  const replay=async()=>{const old=await db.prepare('SELECT * FROM hub_receipts WHERE key=?').bind(receiptKey).first<any>();if(!old)return null;if(old.fingerprint!==fingerprint)throw new HubError(409,'같은 요청 키의 메시지 내용이 달라졌습니다.');return {...JSON.parse(old.response),replayed:true};};
  const previous=await replay();if(previous)return previous;
  const room=await db.prepare("SELECT * FROM hub_rooms WHERE id=? AND project=? AND status!='deleted'").bind(roomId,pid).first<any>();
  if(!room)throw new HubError(404,'이 프로젝트의 대화를 찾을 수 없습니다.');
  const mid=uid(),now=stamp(),result={roomId,messageId:mid};
  try{await db.batch([
    db.prepare("INSERT INTO hub_messages(id,room_id,project,sender,body,created_at) SELECT ?,?,?,'chief',?,? WHERE EXISTS(SELECT 1 FROM hub_rooms WHERE id=? AND project=? AND status NOT IN ('director_thinking','deleted')) AND NOT EXISTS(SELECT 1 FROM hub_generations WHERE room_id=? AND (status='running' OR status LIKE 'retry_pending:%'))").bind(mid,roomId,pid,message,now,roomId,pid,roomId),
    db.prepare("UPDATE hub_rooms SET status='director_thinking',updated_at=? WHERE id=? AND EXISTS(SELECT 1 FROM hub_messages WHERE id=?)").bind(now,roomId,mid),
    db.prepare("UPDATE hub_deliveries SET status='cancelled',lease_id=NULL,expires=NULL WHERE room_id=? AND status IN ('pending','leased') AND EXISTS(SELECT 1 FROM hub_messages WHERE id=?)").bind(roomId,mid),
    db.prepare('INSERT INTO hub_receipts(key,actor,fingerprint,response,created_at) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM hub_messages WHERE id=?)').bind(receiptKey,actor,fingerprint,JSON.stringify(result),now,mid),
  ]);}catch{const existing=await replay();if(existing)return existing;throw new HubError(409,'메시지 전송이 다른 요청과 겹쳤습니다.');}
  if(!await db.prepare('SELECT id FROM hub_messages WHERE id=?').bind(mid).first()){const existing=await replay();if(existing)return existing;throw new HubError(409,'Director가 답변 중입니다. 답변이 끝난 뒤 보내주세요.');}
  await event(actor,pid,'chief.message',mid);const director=await generateDirector(mid);const automatic=await approveFromConversation(actor,pid,roomId,message);return {...result,director,production:automatic};
}
export async function stopRoom(actor:string,rid:string){const db=database(),room=await db.prepare("SELECT * FROM hub_rooms WHERE id=? AND status!='deleted'").bind(text(rid,'대화 ID',100)).first<any>();if(!room)throw new HubError(404,'대화를 찾을 수 없습니다.');await db.batch([
  db.prepare("UPDATE hub_rooms SET status='paused',updated_at=? WHERE id=? AND status!='deleted'").bind(stamp(),rid),
  db.prepare("UPDATE hub_deliveries SET status='cancelled',lease_id=NULL,expires=NULL WHERE room_id=? AND status IN ('pending','leased')").bind(rid),
]);await event(actor,room.project,'room.stop',rid);return {ok:true};}
export async function renameRoom(actor:string,pid:string,rid:string,titleValue:string){const roomId=text(rid,'회의 ID',100),title=text(titleValue,'회의 주제',500),now=stamp(),changed=await database().prepare("UPDATE hub_rooms SET title=?,updated_at=? WHERE id=? AND project=? AND status!='deleted'").bind(title,now,roomId,pid).run();if(!changed.meta.changes)throw new HubError(404,'이 프로젝트의 회의를 찾을 수 없습니다.');await event(actor,pid,'room.rename',roomId);return {ok:true,roomId,title};}

async function refreshReport(reportId:string,roomId:string){const db=database(),counts=await db.prepare("SELECT COUNT(*) total,SUM(CASE WHEN status IN ('approved','rejected') THEN 1 ELSE 0 END) settled,SUM(CASE WHEN status='approved' THEN 1 ELSE 0 END) approved FROM hub_action_items WHERE report_id=?").bind(reportId).first<any>(),done=Number(counts?.total||0)===Number(counts?.settled||0),status=done?(Number(counts?.approved||0)>0?'approved':'rejected'):'pending';await db.batch([db.prepare('UPDATE hub_meeting_reports SET status=?,updated_at=? WHERE id=?').bind(status,stamp(),reportId),db.prepare("UPDATE hub_rooms SET status=CASE WHEN status='awaiting_approval' AND ? THEN 'ready' ELSE status END,updated_at=? WHERE id=?").bind(done?1:0,stamp(),roomId)]);}
export async function approveActionItem(actor:string,pid:string,idValue:string){await ensureStudioSchema();const id=text(idValue,'실행 항목 ID',100),db=database(),item=await db.prepare("SELECT * FROM hub_action_items WHERE id=? AND project=? AND status IN ('pending','blocked')").bind(id,pid).first<any>();if(!item)throw new HubError(409,'승인 대기 중인 실행 항목을 찾을 수 없습니다.');let payload:any={};try{payload=item.payload?JSON.parse(item.payload):{};}catch{}const now=stamp();if(item.action_type==='manual'){await db.prepare("UPDATE hub_action_items SET status='approved',approved_by=?,approved_at=?,error=NULL,updated_at=? WHERE id=? AND project=? AND status IN ('pending','blocked')").bind(actor,now,now,id,pid).run();await studioMessage(pid,item.room_id,`치프가 실행 항목 ‘${item.title}’을 승인했습니다. 담당: ${item.assignee}`);await refreshReport(item.report_id,item.room_id);await event(actor,pid,'action.approved',id);return {ok:true,id,status:'approved',execution:'assigned'};}
 if(!['manual','document','image','video','card-news','shorts','longform','post','landing'].includes(item.action_type))throw new HubError(400,'실행 항목 종류를 확인해주세요.');
 const mode=['shorts','longform','post','landing','document'].includes(item.action_type)?item.action_type:item.action_type==='card-news'?'card-news':item.action_type==='video'?'text-video':'text-image';let jobId=item.production_job_id;try{if(!jobId){const made=await createProduction(actor,pid,{roomId:item.room_id,title:item.title,mode,model:payload.model||'studio',quality:payload.quality||'medium',prompt:payload.prompt||item.description,aspect:payload.aspect||'1:1',resolution:payload.resolution,duration:payload.duration},`action:${id}`);jobId=made.jobId;await db.prepare('UPDATE hub_action_items SET production_job_id=?,updated_at=? WHERE id=? AND project=?').bind(jobId,stamp(),id,pid).run();}const job=await db.prepare('SELECT status FROM hub_production_jobs WHERE id=? AND project=?').bind(jobId,pid).first<any>();if(!job)throw new HubError(404,'연결된 제작 작업을 찾을 수 없습니다.');let execution:any;if(job.status==='blocked')execution=await retryProduction(actor,pid,jobId);else if(job.status==='awaiting_approval')execution=await approveProduction(actor,pid,jobId);else if(['queued','running','complete','approved_result','revision_requested'].includes(job.status))execution={ok:true,jobId,status:job.status,replayed:true};else throw new HubError(409,'제작 작업 상태를 확인해주세요.');await db.prepare("UPDATE hub_action_items SET status='approved',approved_by=?,approved_at=?,error=NULL,updated_at=? WHERE id=? AND project=?").bind(actor,now,now,id,pid).run();await refreshReport(item.report_id,item.room_id);await event(actor,pid,'action.approved',id);return {ok:true,id,status:'approved',productionJobId:jobId,execution};}catch(error){const message=error instanceof Error?error.message:'실행 연결을 확인해주세요.';await db.prepare("UPDATE hub_action_items SET status='blocked',production_job_id=?,error=?,updated_at=? WHERE id=? AND project=?").bind(jobId||null,message.slice(0,1000),stamp(),id,pid).run();await event(actor,pid,'action.blocked',id);throw error;}}
export async function rejectActionItem(actor:string,pid:string,idValue:string){await ensureStudioSchema();const id=text(idValue,'실행 항목 ID',100),db=database(),item=await db.prepare("SELECT * FROM hub_action_items WHERE id=? AND project=? AND status IN ('pending','blocked')").bind(id,pid).first<any>();if(!item)throw new HubError(409,'반려할 실행 항목을 찾을 수 없습니다.');const changed=await db.prepare("UPDATE hub_action_items SET status='rejected',error=NULL,updated_at=? WHERE id=? AND project=? AND status IN ('pending','blocked')").bind(stamp(),id,pid).run();if(!changed.meta.changes)throw new HubError(409,'실행 항목 상태가 이미 변경됐습니다.');await studioMessage(pid,item.room_id,`치프가 실행 항목 ‘${item.title}’을 반려했습니다.`);await refreshReport(item.report_id,item.room_id);await event(actor,pid,'action.rejected',id);return {ok:true,id,status:'rejected'};}
export async function connectMuse(actor:string,pid:string,origin:string){
  if(!env.SITES_SERVICE_TOKEN)throw new HubError(503,'클라우드 연결 인증 설정을 확인해야 합니다.');
  const bytes=crypto.getRandomValues(new Uint8Array(32));const token='vh_'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'');const id=uid(),now=stamp();
  await database().batch([
    database().prepare('UPDATE hub_agent_keys SET enabled=0 WHERE project=?').bind(pid),
    database().prepare('INSERT INTO hub_agent_keys(id,project,hash,enabled,created_at) VALUES(?,?,?,1,?)').bind(id,pid,await hash(token),now),
  ]);await event(actor,pid,'muse.token.rotate',id);
  return {version:3,origin,project:pid,headers:{'OAI-Sites-Authorization':`Bearer ${env.SITES_SERVICE_TOKEN}`,Authorization:`Bearer ${token}`},endpoints:{heartbeat:'/api/muse/heartbeat',receive:'/api/muse/pull',reply:'/api/muse/reply',generationCapabilities:'/api/muse/generation/capabilities',generationPropose:'/api/muse/generation/propose',publicationPull:'/api/muse/publication/pull',publicationAsset:'/api/muse/publication/asset',publicationResult:'/api/muse/publication/result'},interactionMode:'text_reply_no_hub_approval',initialCheck:{method:'GET',path:'/api/muse/info',maxRequests:1},automation:{publicationPull:true,pollSeconds:15},instructions:'PRIVATE CREDENTIAL CONFIG. Never print headers or tokens. You may read generationCapabilities and POST an image/video proposal to generationPropose, but proposals only enter awaiting_approval and never authorize generation. Poll publicationPull. Only a structured publication job with chiefApproval.approved=true authorizes one post to the fixed chief Threads account. Download its media with the same headers, publish exactly once through the official Muse Threads connector, then POST publicationResult with the lease. Never publish ordinary conversation text, never switch accounts or platforms, and never reuse a completed job.'};
}

