async function studioMessage(pid:string,roomId:string,body:string,replyTo:string|null=null){const id=uid();await database().prepare("INSERT INTO hub_messages(id,room_id,project,sender,body,reply_to,created_at) VALUES(?,?,?,'studio',?,?,?)").bind(id,roomId,pid,body,replyTo,stamp()).run();return id;}
function cloudAssetUrl(pid:string,id:string,index:number){return `/api/hub/production/asset?project=${encodeURIComponent(pid)}&jobId=${encodeURIComponent(id)}&index=${index}`;}
