function hfDuration(model:string,value:number){const n=Math.round(Number(value)||5);return model.includes('kling-video')?Math.max(3,Math.min(15,n)):model.includes('seedance')?Math.max(4,Math.min(30,n)):Math.max(2,Math.min(30,n));}
