  await db.prepare("UPDATE hub_production_jobs SET result=?,studio_job_id=?,expires=?,error=NULL,updated_at=? WHERE id=? AND ? IN (SELECT project FROM hub_room_origins WHERE room_id=hub_production_jobs.room_id UNION SELECT hub_production_jobs.project) AND status='running'").bind(JSON.stringify(result),result.requestId,Date.now()+3000,stamp(),job.id,pid).run();
