export async function reviseProduction(actor:string,pid:string,idValue:string,noteValue:string,key:string){const id=text(idValue,'작업 ID',100),note=text(noteValue,'수정 요청',2000),db=database(),old=await db.prepare("SELECT * FROM hub_production_jobs WHERE id=? AND project=? AND status IN ('complete','approved_result')").bind(id,pid).first<any>();if(!old)throw new HubError(409,'수정할 수 있는 완성 결과를 찾을 수 없습니다.');let prior:any={};try{prior=old.result?JSON.parse(old.result):{};}catch{}const result=await createProduction(actor,pid,{roomId:old.room_id,title:`${old.title} · 수정본`,mode:old.mode,model:old.model||'studio',quality:old.quality,prompt:`${old.prompt}\n\n수정 요청: ${note}`,negative:old.negative,aspect:old.aspect,resolution:old.resolution,duration:old.duration,seed:Number(old.seed||42)+1,guidance:old.guidance,referenceId:prior?.reference?.id,referenceName:prior?.reference?.name},`revision:${id}:${key}`);await db.prepare("UPDATE hub_production_jobs SET status='revision_requested',updated_at=? WHERE id=? AND project=?").bind(stamp(),id,pid).run();await studioMessage(pid,old.room_id,`수정 요청을 반영한 새 제작안을 만들었습니다: ${note}`);await event(actor,pid,'production.revision_requested',id);return result;}
