export async function connectStudio(actor:string,pid:string,origin:string){await ensureStudioSchema();if(!env.SITES_SERVICE_TOKEN)throw new HubError(503,'클라우드 연결 인증 설정을 확인해야 합니다.');const bytes=crypto.getRandomValues(new Uint8Array(32)),token='vs_'+btoa(String.fromCharCode(...bytes)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,''),id=uid(),now=stamp();await database().batch([database().prepare('UPDATE hub_studio_keys SET enabled=0 WHERE project=?').bind(pid),database().prepare('INSERT INTO hub_studio_keys(id,project,hash,enabled,created_at) VALUES(?,?,?,1,?)').bind(id,pid,await hash(token),now)]);await event(actor,pid,'studio.token.rotate',id);return {version:1,origin,project:pid,localOrigin:'http://127.0.0.1:8787',headers:{'OAI-Sites-Authorization':`Bearer ${env.SITES_SERVICE_TOKEN}`,Authorization:`Bearer ${token}`},endpoints:{info:'/api/studio/info',heartbeat:'/api/studio/heartbeat',pull:'/api/studio/pull',result:'/api/studio/result'},pollSeconds:2,externalPublicationAllowed:false,instructions:'PRIVATE STUDIO BRIDGE CONFIG. Store beside studio-bridge.mjs on the Windows studio PC. Never print headers or tokens. This bridge may submit only 치프-approved generation jobs to the local studio /api/jobs endpoint and return status/results. It must never publish to SNS.'};}

export async function trash(pid:string,before:number|null=null){const rows=await database().prepare("SELECT *,rowid AS cursor FROM hub_rooms WHERE project=? AND status='deleted' AND rowid<? ORDER BY rowid DESC LIMIT 31").bind(pid,before||Number.MAX_SAFE_INTEGER).all<any>();const rooms=rows.results.slice(0,30);return {rooms,nextCursor:rows.results.length>30?rooms.at(-1)!.cursor:null};}
export async function deleteRoom(actor:string,pid:string,rid:string){const db=database(),roomId=text(rid,'대화 ID',100);const room=await db.prepare('SELECT id FROM hub_rooms WHERE id=? AND project=?').bind(roomId,pid).first();if(!room)throw new HubError(404,'이 프로젝트의 대화를 찾을 수 없습니다.');await db.batch([
 db.prepare("UPDATE hub_rooms SET status='deleted',updated_at=? WHERE id=? AND project=?").bind(stamp(),roomId,pid),
 db.prepare("UPDATE hub_deliveries SET status='cancelled',lease_id=NULL,expires=NULL WHERE room_id=? AND status IN ('pending','leased')").bind(roomId),
]);await event(actor,pid,'room.delete',roomId);return {ok:true,recoverable:true};}
export async function restoreRoom(actor:string,pid:string,rid:string){const roomId=text(rid,'대화 ID',100);const r=await database().prepare("UPDATE hub_rooms SET status='paused',updated_at=? WHERE id=? AND project=? AND status='deleted'").bind(stamp(),roomId,pid).run();if(!r.meta.changes)throw new HubError(404,'휴지통에서 대화를 찾을 수 없습니다.');await event(actor,pid,'room.restore',roomId);return {ok:true,roomId};}

export async function retryDirector(actor:string,pid:string,rid:string,expectedId:string,key:string){
 const db=database(),roomId=text(rid,'대화 ID',100),incomingId=text(expectedId,'메시지 ID',100),receiptKey=actor+':'+text(key,'Idempotency-Key',120),fingerprint=await hash(JSON.stringify({pid,roomId,incomingId,action:'retry'}));
 const replay=async()=>{const old=await db.prepare('SELECT * FROM hub_receipts WHERE key=?').bind(receiptKey).first<any>();if(!old)return null;if(old.fingerprint!==fingerprint)throw new HubError(409,'같은 요청 키로 다른 응답을 재개할 수 없습니다.');return {...JSON.parse(old.response),replayed:true};};
 const previous=await replay();if(previous)return previous;
 const room=await db.prepare("SELECT * FROM hub_rooms WHERE id=? AND project=? AND status='needs_review'").bind(roomId,pid).first<any>();
 if(!room)throw new HubError(409,'중지된 최신 응답만 재개할 수 있습니다. 대화 상태를 다시 확인해주세요.');
 const job=await db.prepare("SELECT * FROM hub_generations WHERE incoming_id=? AND room_id=? AND status='needs_review'").bind(incomingId,roomId).first<any>();
 if(!job)throw new HubError(409,'이 메시지는 재개할 수 있는 상태가 아닙니다.');
 const claim='retry_pending:'+uid(),now=stamp(),result={roomId,incomingId};
 let changes;
 try{changes=await db.batch([
   db.prepare("UPDATE hub_generations SET status=?,error=NULL WHERE incoming_id=? AND status='needs_review' AND EXISTS(SELECT 1 FROM hub_rooms WHERE id=? AND project=? AND status='needs_review') AND incoming_id=(SELECT id FROM hub_messages WHERE room_id=? ORDER BY rowid DESC LIMIT 1)").bind(claim,incomingId,roomId,pid,roomId),
   db.prepare("UPDATE hub_rooms SET status='director_thinking',updated_at=? WHERE id=? AND status='needs_review' AND EXISTS(SELECT 1 FROM hub_generations WHERE incoming_id=? AND status=?)").bind(now,roomId,incomingId,claim),
   db.prepare('INSERT INTO hub_receipts(key,actor,fingerprint,response,created_at) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM hub_generations WHERE incoming_id=? AND status=?)').bind(receiptKey,actor,fingerprint,JSON.stringify(result),now,incomingId,claim),
 ]);}catch{const old=await replay();if(old)return old;throw new HubError(409,'응답 재개 요청이 다른 요청과 겹쳤습니다.');}
 if(!changes[0].meta.changes){const old=await replay();if(old)return old;throw new HubError(409,'응답이 이미 재개됐거나 대화 상태가 변경됐습니다.');}
 await event(actor,pid,'director.retry',incomingId);if(job.response_id)await event(actor,pid,'director.previous_attempt',job.response_id);
 const director=await generateDirector(incomingId,claim);
 if('skipped' in director)await db.prepare("UPDATE hub_generations SET status='needs_review',error=? WHERE incoming_id=? AND status=?").bind('응답 재개 전에 대화 상태가 변경됐습니다.',incomingId,claim).run();
 return {...result,director};
}

export async function editBlockedProduction(actor:string,pid:string,b:any,key:string){
 const id=text(b.id,'작업 ID',100),db=database();
 const old=await db.prepare("SELECT * FROM hub_production_jobs WHERE id=? AND project=? AND status='blocked'").bind(id,pid).first<any>();
 if(!old)throw new HubError(409,'수정할 오류 작업을 찾을 수 없습니다.');
 let prior:any={};try{prior=JSON.parse(old.result||'{}');}catch{}
 const made=await createProduction(actor,pid,{...old,...b,roomId:old.room_id,title:b.title||old.title,referenceId:prior.reference?.id,referenceName:prior.reference?.name},'edit:'+id+':'+key.slice(0,60));
 if(made.jobId===id)throw new HubError(409,'프롬프트 또는 설정을 변경한 뒤 저장해주세요. 같은 조건은 다시 시도를 사용하세요.');
 await db.prepare("UPDATE hub_production_jobs SET status='revision_requested',updated_at=? WHERE id=? AND project=? AND status='blocked'").bind(stamp(),id,pid).run();
 await event(actor,pid,'production.error_edited',id);return made;
}
